import{_ as a,c as n,o as t,ag as r}from"./chunks/framework.Vyheyqg9.js";const h=JSON.parse('{"title":"Optional additions: gaps beyond the supplied homework","description":"","frontmatter":{},"headers":[],"relativePath":"practice/aws/optional-extensions.md","filePath":"practice/aws/optional-extensions.md"}'),s={name:"practice/aws/optional-extensions.md"};function i(o,e,d,c,l,p){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="optional-additions-gaps-beyond-the-supplied-homework" tabindex="-1">Optional additions: gaps beyond the supplied homework <a class="header-anchor" href="#optional-additions-gaps-beyond-the-supplied-homework" aria-label="Permalink to “Optional additions: gaps beyond the supplied homework”">​</a></h1><p>These tasks are <strong>new proposals</strong>, not hidden course requirements. They remain optional. All originally supplied optional/bonus exercises are already mandatory in <a href="./practitioner.html">P01–P08</a> and <a href="./associate.html">A01–A12</a>.</p><p>Use the same store, synthetic data and an owned learning environment. Each extension has an observable result and a failure case; do not create unrelated applications merely to expand the tool list.</p><h2 id="x01-—-duplicate-safe-imports-and-message-handling" tabindex="-1"><span class="hub-section-number">1 </span>X01 — Duplicate-safe imports and message handling <a class="header-anchor" href="#x01-—-duplicate-safe-imports-and-message-handling" aria-label="Permalink to “1 X01 — Duplicate-safe imports and message handling”">​</a></h2><p><strong>After P06.</strong> Choose a stable import/row operation ID and persist idempotency state atomically with the business write where possible. Repeat the same message and upload-event identity, including a simulated crash after the write but before acknowledgement.</p><p><strong>Evidence:</strong> retries produce one intended product/stock effect; a genuinely new operation remains possible; concurrent duplicate claims cannot both succeed. Explain retention of deduplication records and the chosen identity boundary.</p><h2 id="x02-—-recover-database-write-notification-gaps" tabindex="-1"><span class="hub-section-number">2 </span>X02 — Recover database-write/notification gaps <a class="header-anchor" href="#x02-—-recover-database-write-notification-gaps" aria-label="Permalink to “2 X02 — Recover database-write/notification gaps”">​</a></h2><p><strong>After P06/P08.</strong> Introduce a failure after committing business data but before publishing SNS. Implement an outbox or another explicit recovery protocol and a replayable publisher.</p><p><strong>Evidence:</strong> committed changes eventually produce the required notification after recovery; no claim of exactly-once email delivery; duplicate publication/consumption has a documented outcome. Show the failed publisher recovering without rewriting the business record incorrectly.</p><h2 id="x03-—-record-ownership-and-trusted-pricing" tabindex="-1"><span class="hub-section-number">3 </span>X03 — Record ownership and trusted pricing <a class="header-anchor" href="#x03-—-record-ownership-and-trusted-pricing" aria-label="Permalink to “3 X03 — Record ownership and trusted pricing”">​</a></h2><p><strong>After P07/P08.</strong> Derive the acting user from verified identity. Prevent caller A from creating an order for B or reading/changing B&#39;s order. Obtain authoritative prices under a documented rule rather than trusting arbitrary customer-supplied prices.</p><p><strong>Evidence:</strong> allowed own-order actions and denied cross-user actions; forged <code>userId</code>/price does not bypass controls; authorization failures do not mutate data. Preserve the original assignment contract in its evaluated baseline and demonstrate the stronger policy in an explicit extension boundary.</p><h2 id="x04-—-dynamodb-access-patterns-pagination-and-contention" tabindex="-1"><span class="hub-section-number">4 </span>X04 — DynamoDB access patterns, pagination and contention <a class="header-anchor" href="#x04-—-dynamodb-access-patterns-pagination-and-contention" aria-label="Permalink to “4 X04 — DynamoDB access patterns, pagination and contention”">​</a></h2><p><strong>After P04/A08.</strong> Add an access-pattern-driven index for a concrete query. Implement complete pagination and a stable client cursor. Replace a read-then-write stock update with a conditional/transactional operation.</p><p><strong>Evidence:</strong> a dataset spanning multiple pages returns complete intended results; malformed cursors fail predictably; concurrent decrements cannot create negative stock; document consistency and index costs rather than assume the index is always immediately current.</p><h2 id="x05-—-database-backup-and-restore" tabindex="-1"><span class="hub-section-number">5 </span>X05 — Database backup and restore <a class="header-anchor" href="#x05-—-database-backup-and-restore" aria-label="Permalink to “5 X05 — Database backup and restore”">​</a></h2><p><strong>After P08/A08.</strong> Back up synthetic orders, change/delete data deliberately and restore into an isolated target. Verify schema, constraints and representative records, and point an isolated application at the restored database.</p><p><strong>Evidence:</strong> measured recovery time and stated recovery point; the restored API works; no source database is overwritten; retained snapshots and restored targets have a cleanup record. Distinguish replication, backup and tested recovery.</p><h2 id="x06-—-load-connection-pressure-and-bounded-concurrency" tabindex="-1"><span class="hub-section-number">6 </span>X06 — Load, connection pressure and bounded concurrency <a class="header-anchor" href="#x06-—-load-connection-pressure-and-bounded-concurrency" aria-label="Permalink to “6 X06 — Load, connection pressure and bounded concurrency”">​</a></h2><p><strong>After P06/P08/A03.</strong> Run a bounded load test with a fixed duration, request ceiling and stop conditions. Observe API latency/errors, Lambda concurrency, queue age and DB connections. Compare direct/proxied database access where available.</p><p><strong>Evidence:</strong> baseline and changed measurements, one demonstrated bottleneck and a justified improvement. Increasing Lambda concurrency must not be called an improvement if it merely overloads the database. No unbounded traffic generator or uncontrolled retry loop.</p><h2 id="x07-—-incident-diagnosis-and-safe-dlq-redrive" tabindex="-1"><span class="hub-section-number">7 </span>X07 — Incident diagnosis and safe DLQ redrive <a class="header-anchor" href="#x07-—-incident-diagnosis-and-safe-dlq-redrive" aria-label="Permalink to “7 X07 — Incident diagnosis and safe DLQ redrive”">​</a></h2><p><strong>After P06/A09.</strong> Add useful alarms, correlation IDs and a short runbook. Inject a reversible permission/configuration fault, observe alarm delivery, identify the boundary, correct it and redrive only the intended messages.</p><p><strong>Evidence:</strong> actual alarm/notification and diagnostic timeline; recovery avoids repeated business effects; a log identifies the operation without exposing credentials; an empty DLQ alone is not claimed as successful processing.</p><h2 id="x08-—-safe-release-and-rollback-with-schema-compatibility" tabindex="-1"><span class="hub-section-number">8 </span>X08 — Safe release and rollback with schema compatibility <a class="header-anchor" href="#x08-—-safe-release-and-rollback-with-schema-compatibility" aria-label="Permalink to “8 X08 — Safe release and rollback with schema compatibility”">​</a></h2><p><strong>After P08/A11.</strong> Publish identifiable artifacts and introduce a backward-compatible schema change. Release a new version gradually, detect a controlled regression and roll application traffic back while preserving data compatibility.</p><p><strong>Evidence:</strong> known artifact/revision before and after; health criteria trigger the rollback; old/new versions work during the migration window; infrastructure rollback is distinguished from reversing database mutations.</p><h2 id="x09-—-temporary-credentials-least-privilege-and-secret-rotation" tabindex="-1"><span class="hub-section-number">9 </span>X09 — Temporary credentials, least privilege and secret rotation <a class="header-anchor" href="#x09-—-temporary-credentials-least-privilege-and-secret-rotation" aria-label="Permalink to “9 X09 — Temporary credentials, least privilege and secret rotation”">​</a></h2><p><strong>After A02/P07/P08.</strong> Demonstrate federated developer access, role-based workload credentials and scoped deployment roles. Rotate a learning secret using a documented refresh strategy; verify old and new credentials behave as intended.</p><p><strong>Evidence:</strong> allowed and denied actions, no committed keys, workload recovery after rotation and documented cache/connection refresh. Keep the source&#39;s graded account/role setup identifiable rather than silently changing its required exercise.</p><h2 id="x10-—-adversarial-file-and-api-inputs" tabindex="-1"><span class="hub-section-number">10 </span>X10 — Adversarial file and API inputs <a class="header-anchor" href="#x10-—-adversarial-file-and-api-inputs" aria-label="Permalink to “10 X10 — Adversarial file and API inputs”">​</a></h2><p><strong>After P05/P07.</strong> Exercise oversized files/rows, quoted CSV delimiters/newlines, malformed JSON, unexpected content, invalid object keys and forged/expired tokens. Define limits and enforce them before uncontrolled processing.</p><p><strong>Evidence:</strong> valid files still work, failures are bounded and visible, no cross-user object overwrite occurs, and rejected inputs leave no unintended records or runaway retries.</p><h2 id="x11-—-cost-and-resource-ownership-audit" tabindex="-1"><span class="hub-section-number">11 </span>X11 — Cost and resource ownership audit <a class="header-anchor" href="#x11-—-cost-and-resource-ownership-audit" aria-label="Permalink to “11 X11 — Cost and resource ownership audit”">​</a></h2><p><strong>After A11.</strong> Estimate a small workload, record actual resource settings and compare reported costs after billing has settled sufficiently. Inventory dependencies and retained resources across Regions, then remove only the owned disposable resources.</p><p><strong>Evidence:</strong> expected versus observed cost drivers, explicit remaining resources, versions/snapshots/NAT/address/log cleanup and a documented billing-reporting delay. A budget email is not evidence of a hard cap.</p><h2 id="x12-—-ai-quality-and-failure-evaluation" tabindex="-1"><span class="hub-section-number">12 </span>X12 — AI quality and failure evaluation <a class="header-anchor" href="#x12-—-ai-quality-and-failure-evaluation" aria-label="Permalink to “12 X12 — AI quality and failure evaluation”">​</a></h2><p><strong>After A12.</strong> Create a small labeled sentiment/document dataset, include multilingual and boundary-size inputs, and compare output correctness with latency and usage. Test a denied service call, throttling/timeout response and malicious instructions embedded in a document.</p><p><strong>Evidence:</strong> measured quality with known limitations; bounded retries; documents cannot grant tool permissions; model output is validated before downstream effects; error responses and logs protect sensitive content. A successful SDK call alone does not establish useful AI output.</p>',39)])])}const m=a(s,[["render",i]]);export{h as __pageData,m as default};
